const stages={understanding:['Understanding your priorities','فهم أولوياتك'],reviewing:['Finding relevant ART plans','البحث عن خطط تكافل الراجحي'],matching:['Checking suitability','التحقق من الملاءمة'],comparing:['Comparing coverage and trade-offs','مقارنة التغطية والمفاضلات'],analysing:['Reviewing your information','مراجعة معلوماتك'],calculating:['Calculating your scenario','حساب السيناريو'],market:['Consulting available market benchmarks','مراجعة معايير السوق المتاحة'],preparing:['Preparing your recommendation','إعداد توصيتك']};
