 async selectPolicyType(category){this.cancelWork();this.state.profile={...this.state.profile,category};this.state.purchaseFlow={stage:'options',category};this.state.exploreView='response';this.persist();const query=category==='motor'?text(this,'Show me the available motor insurance options as a short clickable list.','اعرض خيارات تأمين المركبات المتاحة في قائمة قصيرة قابلة للنقر.'):text(this,'Show me protection planning options for family protection, balanced savings and education as a short clickable list.','اعرض خيارات تخطيط الحماية للعائلة والادخار المتوازن والتعليم في قائمة قصيرة قابلة للنقر.');return this.sendAdvice(query,{route:false});},
 selectReplyOption(option){this.cancelWork();const current=this.state.purchaseFlow||{},category=current.category||(/wafi|comprehensive|motor|مركبات|شامل|وافي/i.test(option)?'motor':'life'),goal=/education|تعليم/i.test(option)?'education':/balance|future|saving|توازن|مستقبل|ادخار/i.test(option)?'combined':'protect';this.state.profile={...this.state.profile,category,goal,requirements:option};if(category==='life'){this.state.purchaseFlow={stage:'plans',category,lifeGoal:goal,direction:option,aiAssisted:true};this.state.messages.push({role:'user',localized:{en:'Explore '+option+' plans',ar:'استكشاف خطط '+option}},{role:'bot',localized:{en:'I’ve opened three plans in this direction. The AI best fit is highlighted using the priorities and details you have shared; every plan remains selectable.',ar:'عرضت ثلاث خطط ضمن هذا الاتجاه. تم تمييز الأنسب بالذكاء الاصطناعي وفق أولوياتك والتفاصيل التي شاركتها، مع بقاء كل الخطط قابلة للاختيار.'}});}else{this.state.purchaseFlow={stage:'selected',category,option,lifeGoal:current.lifeGoal||goal};this.state.messages.push({role:'user',localized:{en:'Select '+option,ar:'اختيار '+option}},{role:'bot',localized:{en:'I’ve compared this direction with the priority you selected. Here is why it may fit, what value it can offer and the trade-off to review before you continue.',ar:'قارنت هذا الاتجاه بالأولوية التي اخترتها. إليك سبب ملاءمته المحتملة والقيمة التي قد يقدمها والمقايضة التي ينبغي مراجعتها قبل المتابعة.'}});}this.persist();this.render();},
 selectLifePlan(planId){this.cancelWork();const product=catalogue.find(item=>item.id===planId);if(!product)return;const name=product.displayName[this.state.lang],goal=product.kind,isRecommended=recommendedPlan(this.state.profile,goal)?.id===planId;this.state.profile={...this.state.profile,category:'life',goal,selectedProduct:planId,requirements:name};this.state.purchaseFlow={...this.state.purchaseFlow,stage:'calculator',calculatorReturnStage:'plans',category:'life',lifeGoal:goal,option:name,selectedPlan:planId,aiRecommended:isRecommended,aiAssisted:true};this.state.messages.push({role:'user',localized:{en:'Select '+product.displayName.en,ar:'اختيار '+product.displayName.ar}},{role:'bot',localized:{en:'Your selected plan and intent are prefilled in the calculator. You can adjust every value before submitting.',ar:'تمت تعبئة الخطة والهدف المختارين مسبقاً في الحاسبة. يمكنك تعديل كل قيمة قبل الإرسال.'}});this.persist();this.render();requestAnimationFrame(()=>this.host.querySelector('[data-insurance-calculator]')?.click());},
