  const replyOption=e.target.closest('[data-reply-option]');if(replyOption)return this.selectReplyOption(replyOption.dataset.replyOption);
  const lifePlan=e.target.closest('[data-life-plan]');if(lifePlan)return this.selectLifePlan(lifePlan.dataset.lifePlan);
  if(e.target.closest('[data-back-directions]')){this.state.purchaseFlow={stage:'life-intro',category:'life',lifeGoal:this.state.purchaseFlow?.lifeGoal||this.state.profile?.goal||'protect',aiAssisted:true};delete this.state.profile.selectedProduct;this.persist();this.render();return;}
  const policyType=e.target.closest('[data-policy-type]');if(policyType&&!policyType.disabled)return policyType.dataset.policyType==='life'?this.startLifeJourney():this.selectPolicyType(policyType.dataset.policyType);
  if(e.target.closest('[data-flow-calculator]')){if(this.state.purchaseFlow){this.state.purchaseFlow={...this.state.purchaseFlow,calculatorReturnStage:this.state.purchaseFlow.stage,stage:'calculator'};this.persist();this.render();this.host.querySelector('[data-insurance-calculator]')?.click();}return;}
  if(e.target.closest('[data-flow-review]')){if(this.state.purchaseFlow){this.state.purchaseFlow={...this.state.purchaseFlow,stage:'review'};this.persist();this.render();}return;}
  if(e.target.closest('[data-continue-buy]'))return this.advanceToBuy();
  if(e.target.closest('[data-change-policy]')){if(this.state.purchaseFlow?.category==='motor')return this.selectPolicyType('motor');this.state.purchaseFlow=this.state.purchaseFlow?.category==='life'?{stage:'plans',category:'life',lifeGoal:this.state.purchaseFlow.lifeGoal||this.state.profile?.goal||'protect',direction:this.state.purchaseFlow.direction,aiAssisted:true,renewal:Boolean(this.state.purchaseFlow.renewal)}:{stage:'choose'};this.persist();this.render();return;}
