  if(e.target.closest('[data-confirm-purchase]')){this.state.prepared={kind:this.state.purchaseFlow?.renewal?'policy-renewal':'policy-purchase',option:this.state.purchaseFlow?.option||null,status:'saved-locally'};this.state.purchaseFlow={...this.state.purchaseFlow,stage:'complete'};this.persist();this.render();return;}
 const say=e.target.closest('[data-say]');if(say&&!this.state.aiPending&&!this.state.startingGuest){if(this.state.stage==='explore'){this.state.exploreView='response';this.state.exploreJourney=null;}return this.sendAdvice(say.dataset.say);}
 const prepare=e.target.closest('[data-prepare]');if(prepare)return this.prepareAction(prepare.dataset.prepare,prepare.dataset.plan);
 const cap=e.target.closest('[data-capability]');if(cap){const queries={compare:['Compare plans','قارن الخطط'],calculator:['What might affect my premium?','ما العوامل التي تؤثر في القسط؟'],coverage:['How much cover might I need?','ما مبلغ التغطية الذي قد أحتاجه؟'],benefits:['Explain the benefits','اشرح المنافع'],exclusions:['Explain the exclusions','اشرح الاستثناءات'],market:['What are current market trends?','ما اتجاهات السوق الحالية؟']};if(queries[cap.dataset.capability])return this.sendAdvice(text(this,...queries[cap.dataset.capability]));}
